/** A small Creality-Print-shaped file built in code (no design IP), for tests that must always run. */
export function syntheticGcode(opts: {
  objects: { name: string; ids: string[] }[];
  totalGrams: number;
  timeSeconds?: number;
  filler?: number;
}): string {
  const lines = [
    `;TIME:${opts.timeSeconds ?? 3600}`,
    ";Filament used:1.0m",
    ";Layer height:0.200",
    "; HEADER_BLOCK_START",
    "; generated by Creality_Print V7.3.2.6412 on 2026-11-24 at 10:00:00",
    "; total layer number: 10",
    "; HEADER_BLOCK_END",
    "; THUMBNAIL_BLOCK_START",
    "; png begin 2*2 100 0 0 1",
    "; iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAAEklEQVR4nGP4z8DAwMDAxAADAAkMAQBUiIdwAAAAAElFTkSuQmCC",
    "; png end",
    "; THUMBNAIL_BLOCK_END",
    ";LAYER_CHANGE",
  ];
  for (let layer = 0; layer < 2; layer++) {
    for (const o of opts.objects) {
      for (const id of o.ids) {
        lines.push(`; printing object ${o.name} id:${id} copy 0`);
        for (let i = 0; i < (opts.filler ?? 5); i++) lines.push(`G1 X${i} Y${i} E0.01`);
        lines.push(`; stop printing object ${o.name} id:${id} copy 0`);
      }
    }
    lines.push(";LAYER_CHANGE");
  }
  lines.push(
    "; filament used [mm] = 1000.00",
    "; filament used [cm3] = 2.41",
    `; filament used [g] = ${opts.totalGrams}`,
    `; total filament used [g] = ${opts.totalGrams}`,
    "; estimated printing time (normal mode) = 1h 0m 0s",
    "; CONFIG_BLOCK_START",
    "; filament_colour = #000000",
    "; filament_type = PLA",
    "; nozzle_diameter = 0.4",
    "; printer_model = Creality Ender-3 V3 SE",
    "; printer_settings_id = Creality Ender-3 V3 SE 0.4 nozzle",
    "; CONFIG_BLOCK_END",
  );
  return lines.join("\n") + "\n";
}
